import { useMemo, useState } from 'react';
import { JxChip, JxProgressCircle, JxBadge, JxPagination, JxEmptyState, JxButton } from '@jinx-ui/react';

type Status = 'ok' | 'warning' | 'over' | 'paused';

interface ProjectQuota {
  id: string;
  name: string;
  percent: number;
  status: Status;
}

const STATUS_META: Record<Status, { label: string; tone: 'success' | 'warning' | 'danger' | 'alt' }> = {
  ok: { label: 'В рамках квоты', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Превышена', tone: 'danger' },
  paused: { label: 'Приостановлен', tone: 'alt' },
};

const STATUS_ORDER: Status[] = ['ok', 'warning', 'over', 'paused'];

const PROJECTS: ProjectQuota[] = [
  { id: 'p1', name: 'Атлас', percent: 42, status: 'ok' },
  { id: 'p2', name: 'Нордвинд', percent: 88, status: 'warning' },
  { id: 'p3', name: 'Каскад', percent: 104, status: 'over' },
  { id: 'p4', name: 'Пульсар', percent: 15, status: 'ok' },
  { id: 'p5', name: 'Меридиан', percent: 61, status: 'ok' },
  { id: 'p6', name: 'Аврора', percent: 0, status: 'paused' },
  { id: 'p7', name: 'Эклипс', percent: 97, status: 'warning' },
  { id: 'p8', name: 'Тайфун', percent: 120, status: 'over' },
  { id: 'p9', name: 'Обсидиан', percent: 30, status: 'ok' },
  { id: 'p10', name: 'Феникс', percent: 55, status: 'paused' },
  { id: 'p11', name: 'Гравитон', percent: 76, status: 'warning' },
  { id: 'p12', name: 'Сириус', percent: 9, status: 'ok' },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<Set<Status>>(new Set());
  const [page, setPage] = useState(1);

  const toggleStatus = (status: Status) => {
    setActiveStatuses((prev) => {
      const next = new Set(prev);
      if (next.has(status)) {
        next.delete(status);
      } else {
        next.add(status);
      }
      return next;
    });
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(new Set());
    setPage(1);
  };

  const filtered = useMemo(
    () => (activeStatuses.size === 0 ? PROJECTS : PROJECTS.filter((p) => activeStatuses.has(p.status))),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const visible = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        padding: 20,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        maxWidth: 560,
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
        {STATUS_ORDER.map((status) => {
          const isActive = activeStatuses.has(status);
          return (
            <JxChip
              key={status}
              active={isActive}
              removable={isActive}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="По выбранным статусам нет проектов. Сбросьте фильтры, чтобы увидеть весь список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          {visible.map((project) => (
            <div
              key={project.id}
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                gap: 12,
                padding: '12px 8px',
                borderBottom: '1px solid var(--jx-rule)',
              }}
            >
              <span style={{ color: 'var(--jx-text)', flex: 1 }}>{project.name}</span>
              <JxProgressCircle value={Math.min(project.percent, 100)} showValue />
              <JxBadge tone={STATUS_META[project.status].tone}>{STATUS_META[project.status].label}</JxBadge>
            </div>
          ))}
        </div>
      )}

      {visible.length > 0 && pageCount > 1 && (
        <JxPagination total={pageCount} page={page} onPageChange={setPage} />
      )}
    </div>
  );
}

